/bin/bash -lc "curl -fsSL https://platform.openai.com/docs/api-reference/responses/create -o /tmp/openai-responses-doc.html && curl -fsSL https://platform.openai.com/docs/guides/your-data -o /tmp/openai-data-doc.html && python3 - <<'PY'
from html.parser import HTMLParser
class Text(HTMLParser):
    def handle_data(self, data):
        stripped = data.strip()
        if stripped and any(term in stripped.lower() for term in ('store', 'retention', 'training', 'output_text', 'input', 'model')):
            print(stripped[:1600])
for path in ('/tmp/openai-responses-doc.html', '/tmp/openai-data-doc.html'):
    print('\\nSOURCE:', path)
    Text().feed(open(path).read())
PY"

